// Generated by Bug2PR: reproduces a bug from a screen recording.
// Expected behaviour: Filtering by TASK-7141 should show the matching TASK-7141 row that was visible on Page 1 before filtering
import { expect, test } from '@playwright/test';

test("bug2pr: shadcn-search-by-id", async ({ page }) => {
  let before = '';
  await page.setViewportSize({"width":1280,"height":900});
  await test.step('reproduce', async () => {
    await page.goto("/tasks");
    await page.locator("table").first().waitFor();
    await page.getByPlaceholder("Filter by title or ID...").click();
    await page.keyboard.type("TASK-7141");
  });
  await test.step("expected: Filtering by TASK-7141 shows the matching TASK-7141 row in the tasks table", async () => {
    await expect(page.getByRole("table", { name: undefined, exact: true }).filter({ visible: true }).first()).toContainText("TASK-7141");
  });
  void before;
});
